# Public API (cmgr:*)
  @api cmgr:register(name, fn, undoDesc)  @ 126
      @contract  delegates to the global scope — root-level commands are gated-to-global, which is always reachable; the duplicated registration body now lives only in scope:register  @ 125
  @api cmgr:registerAll(tbl)  @ 127
  @api cmgr:rootKeymap()  @ 130
      @contract  returns the bottom-of-stack ('global') keymap directly — used by dispatchers that want to fire ONLY root bindings (e.g. trackerPage's swing editor wants playPause/quit live but page-scoped commands off)  @ 129
  @api cmgr:bind(name, keys)  @ 132
  @api cmgr:bindAll(tbl)  @ 133
  @api cmgr:installManifest(manifest)  @ 144-158
      @invariant  a command resolves to exactly one entry — two scopes declaring it raises  @ 141
      @contract  writes each entry's keys into its scope's keymap and hangs scope.manifest  @ 143
  @api cmgr:entry(name)  @ 161-165
      @contract  raises on a name no manifest declares, so a consumer naming a stale command fails loudly  @ 160
  @api cmgr:auditManifests()  @ 169-190
      @contract  a declared scope's entries and its registrations must correspond, both ways  @ 167
      @contract  a scope that registers a command while declaring no manifest raises  @ 168
  @api cmgr:wrap(name, wrapper)  @ 193-197
      @contract  wrap is a no-op if name has no registered command; wrappers stack (compose outward)  @ 192
  @api cmgr:doBefore(name, before)  @ 202-210
      @contract  doBefore/doAfter accept either a single name or an array of names  @ 199
      @contract  doAfter preserves the original command's return values (the dispatch signal)  @ 200
      @invariant  wraps compose inside the gate — when invoke skips a gated command, no doBefore / doAfter side-effect fires  @ 201
  @api cmgr:doAfter(name, after)  @ 212-222
  @api cmgr:beginPrefix()  @ 244
      @contract  buffer accepts only '0'..'9' and '/'; cancel/finish/invoke each leave the state inactive  @ 243
  @api cmgr:isPrefixActive()  @ 245
  @api cmgr:appendPrefix(ch)  @ 247-251
  @api cmgr:cancelPrefix()  @ 253
  @api cmgr:finishPrefix()  @ 256-274
      @contract  empty buffer or unparseable input → nil pending value; '/' with empty numerator or denominator parses as nil; integer N stored as (N/1)  @ 255
  @api cmgr:prefixRational()  @ 277-279
      @contract  non-consuming reader of the parsed rational; safe to call inside a command body. Returns (nil, nil) when no prefix is pending. State is cleared at the end of invoke, not by this call.  @ 276
  @api cmgr:scope(name)  @ 284-291
      @contract  creates the scope on first request; idempotent thereafter  @ 283
  @api cmgr:push(s)  @ 296-300
      @contract  push(name|scope); creates a named scope if absent. Top-of-stack is the most recently pushed.  @ 295
  @api cmgr:pop(s)  @ 303-307
      @contract  pop(name|scope) asserts the named scope is currently on top; pops it  @ 302
  @api cmgr:lastCommand()  @ 315
      @contract  name and serial of the last body run; unknown or gated-out changes neither  @ 314
  @api cmgr:invoke(name, ...)  @ 320-340
      @contract  returns nil when the command is unknown OR registered on a scope that is not currently reachable (off-stack or blocked by a modal above)  @ 317
      @contract  always prepends the pending prefix (defaulted to 1 when nothing is pending) as the first argument to the command body. Bodies that need to distinguish "user typed 1" from "no prefix" read prefixRational() — it returns (nil, nil) when nothing is pending. State stays live for the call so the body may read it; cleared on return ONLY if there was a pending prefix at entry, so a command body that opens prefix mode (beginPrefix) is not wiped out by its own invoke.  @ 318
      @contract  spring-loaded scope: redirect[] runs fn in-place; keepAlive[] passes; else onBail()  @ 319
  @api cmgr:keysFor(name)  @ 356
  @api cmgr:keychain()  @ 359-376
      @contract  returns one keymap per stack scope in top-down order; modal scopes filter lower keymaps to their passthrough name set, then halt the walk  @ 358
  @api cmgr:keySpec(spec, ImGui)  @ 379-384
      -- ImGui injected so cmgr stays free of REAPER-side imports at module load.
  @api cmgr:commandAtKey(spec, exceptName, ImGui)  @ 390-402
      @contract  reachable command for spec's key (keychain top-down); skips exceptName; nil if free  @ 389
  @api cmgr:bindingSite(name)  @ 405-412
      @contract  scope to edit name's binding in: scope currently binding it, else its gate scope  @ 404
  @api cmgr:noteChars(char)  @ 418-420
      -- Re-read noteLayout on each call so a config change takes effect
      -- without rebuilding vm.
  @api cmgr:keyLabel(spec, ImGui)  @ 507-519
  @api cmgr:keyLabelList(name, ImGui)  @ 522-528
      @contract  list of human labels, one per bound keyspec of the reachable command, or nil if unbound  @ 521
  @api cmgr:keyLabels(name, ImGui)  @ 531-534
      @contract  keyLabelList joined by ' / ', or nil if unbound on the current stack  @ 530
  @api cmgr:tokenForSpec(spec, ImGui)  @ 596-607
      @contract  spec -> stable ASCII token ("Ctrl+Z"); nil if the key has no token name  @ 595
  @api cmgr:specForToken(token, ImGui)  @ 610-625
      @contract  token -> keyspec (bare key | {key, mod...}); (nil, err) on an unknown key/modifier  @ 609
  -- Binding overrides (persisted, hand-editable)
  @api cmgr:loadOverrides(ImGui)  @ 631-646
      @contract  a malformed token is warned and skipped; the command keeps its other (good) bindings  @ 630
  @api cmgr:rebind(scopeName, name, specs, ImGui)  @ 649-659
      @contract  overwrites the scope's binding for name and persists it as tokens (global tier)  @ 648

